import json
from composio import Composio, schema_modifier

# Define the Schema Modifier
@schema_modifier(tools=["HACKERNEWS_GET_LATEST_POSTS"])
def modify_hn_tool(schema, toolkit, data):
    # Check if schema is a string (tool name) or an object
    # The error message said 'str' object has no attribute 'input_parameters'
    # This means 'schema' is likely the tool name string "HACKERNEWS_GET_LATEST_POSTS"
    # and 'data' is the actual schema dictionary/object.

    # Let's inspect the arguments
    target_schema = None
    if hasattr(schema, "input_parameters"):
        target_schema = schema
    elif hasattr(data, "input_parameters"):
        target_schema = data
    elif isinstance(data, dict) and "input_parameters" in data:
        target_schema = data

    if target_schema:
        # Remove the 'page' argument
        if "page" in target_schema.input_parameters["properties"]:
            target_schema.input_parameters["properties"].pop("page")

        # Make the 'size' argument required
        if "required" not in target_schema.input_parameters:
            target_schema.input_parameters["required"] = []

        if "size" not in target_schema.input_parameters["required"]:
            target_schema.input_parameters["required"].append("size")

    return target_schema or schema

# Initialize Composio
composio = Composio()

# Get the tool with the modifier applied
tools = composio.tools.get(
    user_id="default", 
    tools=["HACKERNEWS_GET_LATEST_POSTS"], 
    modifiers=[modify_hn_tool]
)

# Extract the schema for the tool
hn_tool = next((t for t in tools if t.name == "HACKERNEWS_GET_LATEST_POSTS"), None)

if hn_tool:
    # Use .schema or .json_schema or .dict()
    schema_data = getattr(hn_tool, "schema", None) or getattr(hn_tool, "json_schema", None)

    if schema_data is None:
        try:
            schema_data = hn_tool.dict()
        except:
            schema_data = str(hn_tool)

    with open("modified_schema.json", "w") as f:
        json.dump(schema_data, f, indent=4)
    print("Successfully saved modified schema to modified_schema.json")
else:
    print("HACKERNEWS_GET_LATEST_POSTS tool not found in the returned tools list.")

